  insert into public.brainstorm_history (workspace_id, brief, format, duration, source, platforms, ideas, created_by, created_at) values (ws, 'Productivity tips for developers who work from home', 'Short vlog', '30–40 seconds', 'demo', '["TikTok", "Instagram Reels", "LinkedIn"]'::jsonb, '[{"title": "The 3-tab rule", "hook": "I close every tab but three. Here is why.", "outline": "Show 40 tabs, close them, explain the rule, show a calmer screen.", "format": "Short vlog", "platforms": ["TikTok", "Instagram Reels", "LinkedIn"], "adaptations": {"TikTok": "Fast cuts, on-screen counter of tabs.", "Instagram Reels": "Aesthetic desk B-roll, caption-led.", "LinkedIn": "Text post version with the rule and one result."}}, {"title": "Do-not-disturb hour", "hook": "My most productive hour has zero notifications.", "outline": "Phone in a drawer, timer on, what got done, the result.", "format": "Short vlog", "platforms": ["TikTok", "Instagram Reels"], "adaptations": {"TikTok": "Timer overlay counting down.", "Instagram Reels": "Slow, calm edit with lo-fi."}}, {"title": "Shutdown ritual", "hook": "How I stop thinking about code at 6 PM.", "outline": "Write tomorrow''s top task, close laptop, walk.", "format": "Short vlog", "platforms": ["TikTok", "LinkedIn"], "adaptations": {"TikTok": "POV style.", "LinkedIn": "Short reflection with a question."}}]'::jsonb, owner_id, now() - interval '1 days');
